var response = await client.Cities.ListCitiesAsync(
    new Dictionary<string, object?> { ["country"] = "AU", ["state"] = "VIC", ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var city in ((IReadOnlyList<object?>)body["cities"]!).Cast<IReadOnlyDictionary<string, object?>>())
{
    var state = (IReadOnlyDictionary<string, object?>)city["state"]!;
    Console.WriteLine($"{city["id"]} {city["name"]} {city["post_code"]} {state["code"]}");
}
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");
